    function loadSalesConditionsForRule(ruleId) {
      var container = document.getElementById('salesConditionsContainer');
      if (!container) return;
      container.innerHTML = '';
      existingSalesConditions = {};
      var ruleType = getPoolRuleTypeById(ruleId);
      var cond = poolRuleConditions[ruleId];
      if (!cond || typeof cond !== 'object') {
        cond = ruleType === 'personal_sales'
          ? { revenueType: 'Net Sales (税前营业额)', role: [] }
          : {};
      } else {
        cond = Object.assign({}, cond);
      }
      if (ruleType === 'personal_sales') {
        if (!Object.prototype.hasOwnProperty.call(cond, 'role') && !Array.isArray(cond.employee)) {
          cond.role = [];
        }
      }
      if (cond && typeof cond === 'object') {
        normalizeConditionsRoleEmployeeExclusive(cond);
        sortPoolConditionLoadKeys(Object.keys(cond)).forEach(function(type) {
          if (type === 'weekdays') {
            addSalesCondition('weekday', true);
            setSalesConditionValue('weekday', cond.weekdays);
            return;
          }
          // 按个人销售额：角色必选，不加载独立员工条件
          if (ruleType === 'personal_sales' && type === 'employee') return;
          addSalesCondition(type, true);
          if (type === 'role') setSalesConditionValue(type, { role: cond.role || [] });
          else if (type === 'employee') setSalesConditionValue(type, { employeeRoles: cond.employeeRoles, employees: cond.employee });
          else setSalesConditionValue(type, cond[type]);
        });
      }
      if (!existingSalesConditions['revenueType']) {
        addSalesCondition('revenueType', true);
        if (cond && cond.revenueType) setSalesConditionValue('revenueType', cond.revenueType);
        else if (ruleType === 'personal_sales') setSalesConditionValue('revenueType', 'Net Sales (税前营业额)');
      }
      if (ruleType === 'personal_sales') ensureRequiredRoleConditionVisible(cond);
      syncSalesMenuConditionWithRevenueType(true);
      updateSalesConditionMenu();
    }
