    function applyWeekdayConditionValue(card, value) {
      var wMs = card.querySelector('.weekday-condition-select');
      if (!wMs) return;
      var arr = normalizeWeekdayValues(Array.isArray(value) ? value : []);
      wMs.querySelectorAll('input[type="checkbox"]').forEach(function(cb) {
        cb.checked = arr.indexOf(cb.value) >= 0;
      });
      if (wMs.id) refreshMultiTags(wMs.id);
    }

